function stworzOsobeFabryka(imie, wiek) {
  return {
    imie,
    wiek,
    przywitajSie() {
      return `Czesc, jestem ${this.imie}`;
    },
  };
}

const marek = stworzOsobeFabryka("Marek", 40);
console.log(marek.przywitajSie()); // "Czesc, jestem Marek"

class Osoba {
  constructor(imie, wiek) {
    this.imie = imie;
    this.wiek = wiek;
  }
  przywitajSie() {
    return `Czesc, jestem ${this.imie}`;
  }
}

const jan = new Osoba("Jan", 30);
console.log(jan.przywitajSie()); // "Czesc, jestem Jan"

console.log(jan instanceof Osoba); // true - jan zostal stworzony PRZEZ class Osoba
console.log(marek instanceof Object); // true, ale NIE MA "klasy" fabrykujacej
// marek instanceof Osoba -- false! (marek NIE pochodzi z class Osoba)

function stworzOsobe(imie) {
  return { imie };
}

const marek = stworzOsobe("Marek");
// console.log(marek instanceof Osoba); -- false! marek NIE pochodzi z class Osoba

class Osoba {
  constructor(imie) {
    this.imie = imie;
  }
}

const jan = new Osoba("Jan");
console.log(jan instanceof Osoba); // true - POPRAWNIE dziala z class

